    val timelineStartMs: Long,
    val sourceStartMs: Long,
    val sourceEndMs: Long,
)

/**
 * Where the music plays inside a video of [videoDurationMs]. Music longer than the remaining video
 * is cut at the video end; music starting at or after the end doesn't play (null).
