package com.savie.precut.model

import org.junit.Assert.assertEquals
import org.junit.Assert.assertNull
import org.junit.Test

class AudioPlacementTest {

    private fun music(start: Long = 0L, trimStart: Long = 0L, trimEnd: Long = 30_000L) =
        AudioClip("m", "content://m", sourceDurationMs = 60_000L, timelineStartMs = start, trimStartMs = trimStart, trimEndMs = trimEnd)

    @Test
    fun shorterMusic_playsFullyAndEndsEarly() {
        assertEquals(AudioPlacement(2_000L, 0L, 30_000L), music(start = 2_000L).placementWithin(60_000L))
    }

    @Test
    fun longerMusic_isCutAtVideoEnd() {
        // 30 s of music starting at 5 s in a 20 s video: 15 s play.
        assertEquals(AudioPlacement(5_000L, 0L, 15_000L), music(start = 5_000L).placementWithin(20_000L))
    }

    @Test
    fun trimmedMusic_cutsFromItsTrimStart() {
        assertEquals(AudioPlacement(0L, 10_000L, 20_000L), music(trimStart = 10_000L, trimEnd = 40_000L).placementWithin(10_000L))
    }

    @Test
    fun musicStartingAtOrAfterVideoEnd_doesNotPlay() {
        assertNull(music(start = 20_000L).placementWithin(20_000L))
        assertNull(music(start = 25_000L).placementWithin(20_000L))
        assertNull(music().placementWithin(0L))
    }
}
