        val missingIds: Set<String> = emptySet(),
        val canUndo: Boolean = false,
        val canRedo: Boolean = false,
    ) : EditorUiState
}

sealed interface EditorEvent {
    data class SomeFilesSkipped(val count: Int) : EditorEvent
    data object NothingImported : EditorEvent
    data object SpeedNotForPhotos : EditorEvent
    /** The screen should open the audio file picker. */
    data object PickMusic : EditorEvent
    data object MusicImportFailed : EditorEvent
    /** The screen should ask for RECORD_AUDIO, then call back into the audio controller. */
    data object RequestMicPermission : EditorEvent
    data object RecordingFailed : EditorEvent
    data object NothingToExtract : EditorEvent
    /** The screen should open the single-item media picker to replace the selected clip. */
    data object PickReplacement : EditorEvent
}

@OptIn(FlowPreview::class)
@HiltViewModel
class EditorViewModel @Inject constructor(
    savedStateHandle: SavedStateHandle,
    private val repository: ProjectRepository,
    private val previewController: PreviewController,
    private val importer: MediaImporter,
    /** For the timeline's thumbnail tiles. */
    val thumbnails: ThumbnailLoader,
    /** For audio clips' waveforms. */
    val waveforms: WaveformLoader,
    private val clock: Clock,
    voiceRecorder: VoiceRecorder,
    private val probe: MediaProbe,
    @ApplicationScope private val appScope: CoroutineScope,
) : ViewModel() {

    val projectId = savedStateHandle.requireProjectId()

    private val _uiState = MutableStateFlow<EditorUiState>(EditorUiState.Loading)
    val uiState: StateFlow<EditorUiState> = _uiState.asStateFlow()

    private val _events = Channel<EditorEvent>(Channel.BUFFERED)
    val events: Flow<EditorEvent> = _events.receiveAsFlow()

    val previewState: StateFlow<PreviewState> = previewController.state

    /** Whether Split would do something at the current playhead. */
    val canSplit: StateFlow<Boolean> = combine(_uiState, previewState) { ui, preview ->
        ui is EditorUiState.Ready && EditReducer.canSplit(ui.project, preview.positionMs)
    }.stateIn(viewModelScope, SharingStarted.Eagerly, false)

    /** For attaching the video surface only; control playback through the event methods. */
    val player: Player get() = previewController.player

    private val host = object : EditorHost {
        override val ready: EditorUiState.Ready? get() = _uiState.value as? EditorUiState.Ready
        override val positionMs: Long get() = previewState.value.positionMs
        override val scope get() = viewModelScope
        override fun applyEdit(action: EditAction) = this@EditorViewModel.applyEdit(action)
        override fun update(transform: (EditorUiState.Ready) -> EditorUiState.Ready) = updateReady(transform)
        override fun send(event: EditorEvent) {
            viewModelScope.launch { _events.send(event) }
        }
        override fun newId(): String = this@EditorViewModel.newId()
        override fun targetClipId(): String? = this@EditorViewModel.targetClipId()
    }

    /** Audio lanes, extract, voiceover and audio-clip tools. */
    val audio = EditorAudio(host, importer, previewController, voiceRecorder)

    /** Edits, undo history and auto-save; set once the project has loaded. */
    private var session: ProjectSession? = null

    /** Latest edited project; the preview rebuilds once edits pause, so rapid edits rebuild once. */
    private val pendingPreview = MutableStateFlow<Project?>(null)

    init {
        viewModelScope.launch {
            val project = repository.load(projectId)
            if (project == null) {
                _uiState.value = EditorUiState.NotFound
                return@launch
            }
            session = ProjectSession(project, repository, clock, appScope, viewModelScope)
            val missing = findMissing(project)
            previewController.setProject(playable(project, missing))
            _uiState.value = EditorUiState.Ready(project, missingIds = missing)
        }
        viewModelScope.launch {
            pendingPreview.filterNotNull().debounce(PREVIEW_REBUILD_DEBOUNCE_MS).collect { project ->
                val missing = (_uiState.value as? EditorUiState.Ready)?.missingIds.orEmpty()
                val playable = playable(project, missing)
                val resumeAt = previewState.value.positionMs.coerceAtMost(playable.totalDurationMs())
                previewController.setProject(playable, resumeAt)
            }
        }
    }

    // Playback

    fun onPlayPause() = previewController.togglePlayPause()

    fun onScrubStart() = previewController.pause()

    fun onSeek(positionMs: Long) = previewController.seekTo(positionMs)

    /** Leaving the screen pauses playback and finishes (keeps) any voiceover in progress. */
    fun onScreenStopped() {
        audio.onRecordStop()
        previewController.pause()
        session?.flush()
    }

    // Undo / redo

    fun onUndo() = session?.undo()?.let(::showRestored)

    fun onRedo() = session?.redo()?.let(::showRestored)

    /** Shows an undone/redone project, dropping selections that no longer exist. */
    private fun showRestored(project: Project) {
        val history = session?.history ?: return
        updateReady { ready ->
            ready.copy(
                project = project,
                canUndo = history.canUndo,
                canRedo = history.canRedo,
                selectedClipId = ready.selectedClipId?.takeIf { id -> project.clips.any { it.id == id } },
                selectedTextId = ready.selectedTextId?.takeIf { id -> project.textOverlays.any { it.id == id } },
                selectedAudioId = ready.selectedAudioId?.takeIf { id -> project.audioClips.any { it.id == id } },
                activeTool = null,
            )
        }
        previewController.pause()
        pendingPreview.value = project
    }

    // Missing media

    fun onRemoveMissing() {
        val ready = _uiState.value as? EditorUiState.Ready ?: return
        val clipIds = ready.project.clips.map { it.id }.filter { it in ready.missingIds }.toSet()
        val audioIds = ready.project.audioClips.map { it.id }.filter { it in ready.missingIds }.toSet()
        applyEdit(EditAction.RemoveItems(clipIds, audioIds))
        updateReady { it.copy(missingIds = emptySet(), selectedClipId = null, selectedAudioId = null, activeTool = null) }
    }

    /** Replace the selected (or playhead) clip's media, e.g. a missing one. */
    fun onReplaceClip() {
        val clipId = targetClipId() ?: return
        updateReady { it.copy(selectedClipId = clipId) }
        viewModelScope.launch { _events.send(EditorEvent.PickReplacement) }
    }

    fun onReplacementPicked(uri: String?) {
        val clipId = (_uiState.value as? EditorUiState.Ready)?.selectedClipId ?: return
        if (uri == null) return
        viewModelScope.launch {
            val imported = importer.import(listOf(uri)).imported.firstOrNull()
            if (imported == null) {
                _events.send(EditorEvent.NothingImported)
                return@launch
            }
            updateReady { it.copy(missingIds = it.missingIds - clipId) }
            applyEdit(EditAction.ReplaceClip(clipId, imported.uri, imported.info))
        }
    }

    private suspend fun findMissing(project: Project): Set<String> =
        (project.clips.map { it.id to it.uri } + project.audioClips.map { it.id to it.uri })
            .filterNot { (_, uri) -> probe.isReadable(uri) }
            .map { it.first }
            .toSet()

    /** The project without media that can't be opened, so the rest still previews. */
    private fun playable(project: Project, missing: Set<String>): Project =
        if (missing.isEmpty()) {
            project
        } else {
            project.copy(clips = project.clips.filterNot { it.id in missing }, audioClips = project.audioClips.filterNot { it.id in missing })
        }

    // Selection and tools

    fun onClipSelected(clipId: String?) {
        dropBlankSelectedText()
        updateReady {
            val clip = it.project.clips.firstOrNull { c -> c.id == clipId }
            // Keep a clip tool open when switching clips, unless it doesn't apply (speed on a photo).
            val keepTool = clip != null && it.activeTool in CLIP_TOOLS &&
                !(it.activeTool == EditorTool.SPEED && clip.type == ClipType.IMAGE)
            it.copy(
                selectedClipId = clipId,
                selectedTextId = null,
                selectedAudioId = null,
                audioMenuOpen = it.audioMenuOpen && clipId == null,
                activeTool = if (keepTool) it.activeTool else null,
            )
        }
    }

    fun onTextSelected(textId: String?) {
        dropBlankSelectedText()
        updateReady {
            it.copy(
                selectedTextId = textId,
                selectedClipId = null,
                selectedAudioId = null,
                audioMenuOpen = false,
                activeTool = if (textId != null) EditorTool.TEXT else null,
            )
        }
    }

    fun onToolSelected(tool: EditorTool) {
        val ready = _uiState.value as? EditorUiState.Ready ?: return
        if (ready.activeTool == tool) return onToolClosed()
        if (ready.selectedAudioId != null && tool in AUDIO_TOOLS) {
            updateReady { it.copy(activeTool = tool) }
            return
        }
        when (tool) {
            EditorTool.RATIO, EditorTool.VOICEOVER -> updateReady { it.copy(activeTool = tool) }
            EditorTool.TEXT -> addText(ready)
            EditorTool.VOICE, EditorTool.BEATS -> Unit // audio-only tools
            EditorTool.TRIM, EditorTool.SPEED, EditorTool.FILTER, EditorTool.VOLUME, EditorTool.FADE -> {
                val clipId = targetClipId() ?: return
                val clip = ready.project.clips.first { it.id == clipId }
                if (tool == EditorTool.SPEED && clip.type == ClipType.IMAGE) {
                    viewModelScope.launch { _events.send(EditorEvent.SpeedNotForPhotos) }
                    return
                }
                updateReady { it.copy(selectedClipId = clipId, selectedTextId = null, selectedAudioId = null, activeTool = tool) }
            }
        }
    }

    fun onToolClosed() {
        dropBlankSelectedText()
        // Audio selection stays so its toolbar comes back, like CapCut.
        updateReady { it.copy(activeTool = null, selectedTextId = null) }
    }

    fun onAudioMenu(open: Boolean) = updateReady {
        it.copy(audioMenuOpen = open, selectedClipId = null, selectedTextId = null, selectedAudioId = null, activeTool = null)
    }

    // Edits

    fun onSplit() = applyEdit(EditAction.SplitClip(previewState.value.positionMs, newId()))

    fun onDelete() {
        val clipId = targetClipId() ?: return
        applyEdit(EditAction.DeleteClip(clipId))
        updateReady { it.copy(selectedClipId = null, activeTool = null) }
    }

    fun onDuplicate() {
        val clipId = targetClipId() ?: return
        applyEdit(EditAction.DuplicateClip(clipId, newId()))
    }

    fun onTrim(clipId: String, trimStartMs: Long, trimEndMs: Long) =
        applyEdit(EditAction.TrimClip(clipId, trimStartMs, trimEndMs))

    fun onMove(from: Int, to: Int) = applyEdit(EditAction.MoveClip(from, to))

    fun onRotate() {
        val clipId = targetClipId() ?: return
        applyEdit(EditAction.RotateClip(clipId))
    }

    fun onSpeedChanged(speed: Float) {
        val clipId = (_uiState.value as? EditorUiState.Ready)?.selectedClipId ?: return
        applyEdit(EditAction.SetSpeed(clipId, speed))
    }

    fun onFilterSelected(filter: FilterType) {
        val clipId = (_uiState.value as? EditorUiState.Ready)?.selectedClipId ?: return
        applyEdit(EditAction.SetFilter(clipId, filter))
    }

    fun onAspectRatioSelected(aspectRatio: AspectRatio) = applyEdit(EditAction.SetAspectRatio(aspectRatio))

    fun onTextChanged(overlay: TextOverlay) = applyEdit(EditAction.UpdateText(overlay))

    fun onTextMoved(textId: String, xNorm: Float, yNorm: Float) {
        val overlay = findText(textId) ?: return
        applyEdit(EditAction.UpdateText(overlay.copy(xNorm = xNorm, yNorm = yNorm)))
    }

    fun onTextTimingChanged(textId: String, startMs: Long, endMs: Long) {
        val overlay = findText(textId) ?: return
        applyEdit(EditAction.UpdateText(overlay.copy(startMs = startMs, endMs = endMs)))
    }

    fun onClipVolumeChanged(volume: Float) {
        val clipId = (_uiState.value as? EditorUiState.Ready)?.selectedClipId ?: return
        applyEdit(EditAction.SetClipVolume(clipId, volume))
    }

    fun onClipMutedChanged(muted: Boolean) {
        val clipId = (_uiState.value as? EditorUiState.Ready)?.selectedClipId ?: return
        applyEdit(EditAction.SetClipMuted(clipId, muted))
    }

    fun onClipFadesChanged(fadeInMs: Long, fadeOutMs: Long) {
        val clipId = (_uiState.value as? EditorUiState.Ready)?.selectedClipId ?: return
        applyEdit(EditAction.SetClipFades(clipId, fadeInMs, fadeOutMs))
    }

    /** CapCut's "Mute clip audio" switch beside the timeline. */
    fun onToggleOriginalAudio() {
        val ready = _uiState.value as? EditorUiState.Ready ?: return
        applyEdit(EditAction.SetOriginalAudioMuted(!ready.project.originalAudioMuted))
    }

    fun onDeleteText() {
        val textId = (_uiState.value as? EditorUiState.Ready)?.selectedTextId ?: return
        applyEdit(EditAction.DeleteText(textId))
        updateReady { it.copy(selectedTextId = null, activeTool = null) }
    }

    /** New text at the playhead, lasting [DEFAULT_TEXT_DURATION_MS], selected for editing. */
    private fun addText(ready: EditorUiState.Ready) {
        if (ready.project.clips.isEmpty()) return
        val start = previewState.value.positionMs
        val overlay = TextOverlay(id = newId(), text = "", startMs = start, endMs = start + DEFAULT_TEXT_DURATION_MS)
        applyEdit(EditAction.AddText(overlay))
        updateReady { it.copy(selectedTextId = overlay.id, selectedClipId = null, activeTool = EditorTool.TEXT) }
    }

    /** A text left empty when its panel closes is removed rather than kept invisible. */
    private fun dropBlankSelectedText() {
        val ready = _uiState.value as? EditorUiState.Ready ?: return
        val text = ready.selectedTextId?.let(::findText) ?: return
        if (text.text.isBlank()) applyEdit(EditAction.DeleteText(text.id))
    }

    private fun findText(textId: String): TextOverlay? =
        (_uiState.value as? EditorUiState.Ready)?.project?.textOverlays?.firstOrNull { it.id == textId }

    fun onMediaPicked(uris: List<String>) {
        val ready = _uiState.value as? EditorUiState.Ready ?: return
        if (uris.isEmpty() || ready.isImporting) return
        updateReady { it.copy(isImporting = true) }
        viewModelScope.launch {
            try {
                val result = importer.import(uris)
                if (result.imported.isEmpty()) {
                    _events.send(EditorEvent.NothingImported)
                    return@launch
                }
                if (result.failedCount > 0) _events.send(EditorEvent.SomeFilesSkipped(result.failedCount))
                applyEdit(EditAction.AddClips(result.imported.map { clipFromMedia(newId(), it.uri, it.info) }))
            } finally {
                updateReady { it.copy(isImporting = false) }
            }
        }
    }

    /** The clip a clip tool acts on: the selected one, otherwise the one under the playhead. */
    private fun targetClipId(): String? {
        val ready = _uiState.value as? EditorUiState.Ready ?: return null
        ready.selectedClipId?.let { return it }
        val position = ready.project.clipAt(previewState.value.positionMs) ?: return null
        return ready.project.clips[position.index].id
    }

    private fun applyEdit(action: EditAction) {
        val ready = _uiState.value as? EditorUiState.Ready ?: return
        val currentSession = session ?: return
        val edited = currentSession.apply(action) ?: return
        _uiState.value = ready.copy(project = edited, canUndo = currentSession.history.canUndo, canRedo = false)
        previewController.pause()
        pendingPreview.value = edited
    }

    private fun updateReady(transform: (EditorUiState.Ready) -> EditorUiState.Ready) =
        _uiState.update { if (it is EditorUiState.Ready) transform(it) else it }

    private fun newId() = UUID.randomUUID().toString()

    override fun onCleared() {
        session?.flush()
        audio.release()
        previewController.release()
    }

    private companion object {
        const val PREVIEW_REBUILD_DEBOUNCE_MS = 150L
        const val DEFAULT_TEXT_DURATION_MS = 3_000L
        val CLIP_TOOLS = setOf(EditorTool.TRIM, EditorTool.SPEED, EditorTool.FILTER, EditorTool.VOLUME, EditorTool.FADE)
        val AUDIO_TOOLS = setOf(EditorTool.VOLUME, EditorTool.FADE, EditorTool.SPEED, EditorTool.VOICE, EditorTool.BEATS)
    }
}

package com.savie.precut.model.edit

import com.savie.precut.model.Clip
import com.savie.precut.model.MediaInfo
import com.savie.precut.model.clipFromMedia
import com.savie.precut.model.ClipType
import com.savie.precut.model.MAX_VOLUME
import com.savie.precut.model.Project
import com.savie.precut.model.TextOverlay
import com.savie.precut.model.clipAt
import com.savie.precut.model.timelineOffsetToSourceMs
import com.savie.precut.model.totalDurationMs

/** Shortest clip a trim or split may produce, in source time; also the shortest text overlay. */
const val MIN_CLIP_DURATION_MS = 100L
const val MIN_SPEED = 0.25f
const val MAX_SPEED = 4f

object EditReducer {

    /** Returns the project with [action] applied, or the same instance if nothing changed. */
    fun reduce(project: Project, action: EditAction): Project {
        val edited = when (action) {
            is EditAction.AddClips -> project.addClips(action)
            is EditAction.DeleteClip -> project.withClips(project.clips.filterNot { it.id == action.clipId })
            is EditAction.SplitClip -> project.split(action)
            is EditAction.MoveClip -> project.move(action.from, action.to)
            is EditAction.DuplicateClip -> project.duplicate(action)
            is EditAction.TrimClip -> project.updateClip(action.clipId) { it.trimmed(action.trimStartMs, action.trimEndMs) }
            is EditAction.SetSpeed -> project.updateClip(action.clipId) {
                if (it.type == ClipType.IMAGE) it else it.copy(speed = action.speed.coerceIn(MIN_SPEED, MAX_SPEED))
            }
            is EditAction.SetFilter -> project.updateClip(action.clipId) { it.copy(filter = action.filter) }
            is EditAction.RotateClip -> project.updateClip(action.clipId) { it.copy(rotationDegrees = (it.rotationDegrees + 90) % 360) }
            is EditAction.SetAspectRatio ->
                if (project.aspectRatio == action.aspectRatio) project else project.copy(aspectRatio = action.aspectRatio)
            is EditAction.AddText -> project.copy(textOverlays = project.textOverlays + action.overlay)
            is EditAction.UpdateText -> project.updateText(action.overlay)
            is EditAction.DeleteText -> project.textOverlays.filterNot { it.id == action.overlayId }
                .let { if (it.size == project.textOverlays.size) project else project.copy(textOverlays = it) }
            is EditAction.SetClipVolume -> project.updateClip(action.clipId) { it.copy(volume = action.volume.coerceIn(0f, MAX_VOLUME)) }
            is EditAction.SetClipMuted -> project.updateClip(action.clipId) { it.copy(muted = action.muted) }
            is EditAction.ReplaceClip -> project.updateClip(action.clipId) { it.replacedWith(action.uri, action.info) }
            is EditAction.RemoveItems -> {
                val clips = project.clips.filterNot { it.id in action.clipIds }
                val audio = project.audioClips.filterNot { it.id in action.audioIds }
                if (clips.size == project.clips.size && audio.size == project.audioClips.size) {
                    project
                } else {
                    project.copy(clips = clips, audioClips = audio)
                }
            }
            is EditAction.AudioEdit -> project.applyAudioEdit(action)
        }
        return if (edited === project) project else edited.withClampedTexts()
    }

    /** True if [reduce] would split something at [atTimelineMs]. Used to enable the Split button. */
    fun canSplit(project: Project, atTimelineMs: Long): Boolean = splitPoint(project, atTimelineMs) != null

    /**
     * Keeps every text overlay inside the timeline, at least [MIN_CLIP_DURATION_MS] long (when the
     * timeline allows) and positioned within the frame. With no clips, overlays are dropped.
     */
    private fun Project.withClampedTexts(): Project {
        if (textOverlays.isEmpty()) return this
        val total = totalDurationMs()
        if (total == 0L) return copy(textOverlays = emptyList())
        val minLength = MIN_CLIP_DURATION_MS.coerceAtMost(total)
        val clamped = textOverlays.map { overlay ->
            val start = overlay.startMs.coerceIn(0L, total - minLength)
            val end = overlay.endMs.coerceIn(start + minLength, total)
            overlay.copy(
                startMs = start,
                endMs = end,
                xNorm = overlay.xNorm.coerceIn(0f, 1f),
                yNorm = overlay.yNorm.coerceIn(0f, 1f),
            )
        }
        return if (clamped == textOverlays) this else copy(textOverlays = clamped)
    }

    private fun Project.updateText(overlay: TextOverlay): Project {
        val index = textOverlays.indexOfFirst { it.id == overlay.id }
        if (index < 0 || textOverlays[index] == overlay) return this
        return copy(textOverlays = textOverlays.toMutableList().also { it[index] = overlay })
    }

    private fun Project.addClips(action: EditAction.AddClips): Project {
        if (action.clips.isEmpty()) return this
        val index = (action.atIndex ?: clips.size).coerceIn(0, clips.size)
        return copy(clips = clips.subList(0, index) + action.clips + clips.subList(index, clips.size))
    }

    private fun Project.split(action: EditAction.SplitClip): Project {
        val (index, sourceMs) = splitPoint(this, action.atTimelineMs) ?: return this
        val clip = clips[index]
        val first = clip.copy(trimEndMs = sourceMs)
        val second = clip.copy(id = action.newClipId, trimStartMs = sourceMs)
        return copy(clips = clips.subList(0, index) + listOf(first, second) + clips.subList(index + 1, clips.size))
    }

    /** Index of the clip to split and the split time in its source, or null if too close to an edge. */
    private fun splitPoint(project: Project, atTimelineMs: Long): Pair<Int, Long>? {
        val position = project.clipAt(atTimelineMs) ?: return null
        val clip = project.clips[position.index]
        val sourceMs = clip.timelineOffsetToSourceMs(position.offsetMs)
        val tooClose = sourceMs - clip.trimStartMs < MIN_CLIP_DURATION_MS ||
            clip.trimEndMs - sourceMs < MIN_CLIP_DURATION_MS
        return if (tooClose) null else position.index to sourceMs
    }

    private fun Project.move(from: Int, to: Int): Project {
        if (from !in clips.indices || to !in clips.indices || from == to) return this
        val mutable = clips.toMutableList()
        mutable.add(to, mutable.removeAt(from))
        return copy(clips = mutable)
    }

    private fun Project.duplicate(action: EditAction.DuplicateClip): Project {
        val index = clips.indexOfFirst { it.id == action.clipId }
        if (index < 0) return this
        return copy(clips = clips.toMutableList().also { it.add(index + 1, clips[index].copy(id = action.newClipId)) })
    }

    private fun Project.withClips(newClips: List<Clip>): Project =
        if (newClips.size == clips.size) this else copy(clips = newClips)

    private fun Project.updateClip(clipId: String, transform: (Clip) -> Clip): Project {
        val index = clips.indexOfFirst { it.id == clipId }
        if (index < 0) return this
        val updated = transform(clips[index])
        if (updated == clips[index]) return this
        return copy(clips = clips.toMutableList().also { it[index] = updated })
    }

    private fun Clip.replacedWith(uri: String, info: MediaInfo): Clip {
        val fresh = clipFromMedia(id, uri, info)
        val wantedLength = trimEndMs - trimStartMs
        return fresh.copy(
            trimStartMs = 0L,
            trimEndMs = wantedLength.coerceIn(MIN_CLIP_DURATION_MS.coerceAtMost(fresh.sourceDurationMs), fresh.sourceDurationMs),
            speed = if (fresh.type == ClipType.VIDEO && type == ClipType.VIDEO) speed else 1f,
            volume = volume,
            muted = muted,
            filter = filter,
            rotationDegrees = rotationDegrees,
            fadeInMs = fadeInMs,
            fadeOutMs = fadeOutMs,
        )
    }

    private fun Clip.trimmed(requestedStartMs: Long, requestedEndMs: Long): Clip {
        // Clips shorter than the minimum can't be trimmed at all; keep them whole.
        val minLength = MIN_CLIP_DURATION_MS.coerceAtMost(sourceDurationMs)
        val start = requestedStartMs.coerceIn(0L, sourceDurationMs - minLength)
        val end = requestedEndMs.coerceIn(start + minLength, sourceDurationMs)
        return copy(trimStartMs = start, trimEndMs = end)
    }
}

package com.savie.precut.media

import com.savie.precut.model.Clip
import com.savie.precut.model.ClipType
import com.savie.precut.model.FilterType
import com.savie.precut.model.OutputSize
import com.savie.precut.model.Project
import com.savie.precut.model.TextOverlay
import com.savie.precut.model.outputSizeFor
import com.savie.precut.model.audioLanes
import com.savie.precut.model.edit.clampFades
import com.savie.precut.model.placementWithin
import com.savie.precut.model.timelineDurationMs
import com.savie.precut.model.totalDurationMs

/**
 * Pure description of the Media3 composition for a project. Kept free of Media3/Android types so
 * the Project → composition mapping can be unit-tested on the JVM.
 */
data class CompositionSpec(
    val items: List<ItemSpec>,
    val outputSize: OutputSize,
    /** Applied once to the whole composition, in timeline time. */
    val texts: List<TextSpec> = emptyList(),
    /** Audio rows, each mixed in as its own audio-only sequence. */
    val audioLanes: List<List<AudioItemSpec>> = emptyList(),
)

/** One audio clip after placement: silence for [gapBeforeMs], then its (already cut) range. */
data class AudioItemSpec(
    val uri: String,
    val sourceDurationMs: Long,
    val gapBeforeMs: Long,
    val clipStartMs: Long,
    val clipEndMs: Long,
    val speed: Float,
    val sound: SoundSpec,
)

/** How an item's audio is shaped, in its timeline length [lengthMs]. */
data class SoundSpec(
    val volume: Float = 1f,
    val fadeInMs: Long = 0L,
    val fadeOutMs: Long = 0L,
    val lengthMs: Long = 0L,
    val pitch: Float = 1f,
)

/** Look shared by every item: colour effects, then user rotation, then fit into the frame. */
data class VisualSpec(
    val filter: List<FilterEffect> = emptyList(),
    /** Clockwise, 0/90/180/270. */
    val rotationDegrees: Int = 0,
)

sealed interface ItemSpec {
    val visual: VisualSpec

    data class Video(
        val uri: String,
        val sourceDurationMs: Long,
        val clipStartMs: Long,
        val clipEndMs: Long,
        val speed: Float = 1f,
        /** The clip's own sound; volume 0 when muted or when all original audio is muted. */
        val sound: SoundSpec = SoundSpec(),
        override val visual: VisualSpec = VisualSpec(),
    ) : ItemSpec

    data class Image(
        val uri: String,
        val durationMs: Long,
        override val visual: VisualSpec = VisualSpec(),
    ) : ItemSpec
}

/** A text overlay ready to render: pixel size in the output frame and a Media3 NDC anchor. */
data class TextSpec(
    val id: String,
    val text: String,
    val startUs: Long,
    val endUs: Long,
    /** -1 (left) .. 1 (right). */
    val anchorX: Float,
    /** -1 (bottom) .. 1 (top). */
    val anchorY: Float,
    val textSizePx: Float,
    val colorArgb: Int,
    val backgroundArgb: Int?,
)

/**
 * Text sizes are "sp on a [TEXT_REFERENCE_WIDTH_DP]-wide screen", scaled to the output's short
 * side, so the editor's on-screen ghost and the export agree regardless of resolution.
 */
const val TEXT_REFERENCE_WIDTH_DP = 360f

fun textSizePx(textSizeSp: Float, frameShortSidePx: Int): Float = textSizeSp * frameShortSidePx / TEXT_REFERENCE_WIDTH_DP

/** Maps a 0..1 position (y down) to Media3's normalized device coordinates (y up). */
fun toNdc(xNorm: Float, yNorm: Float): Pair<Float, Float> = (xNorm * 2f - 1f) to (1f - yNorm * 2f)

fun compositionSpecOf(project: Project): CompositionSpec {
    val outputSize = outputSizeFor(project.aspectRatio)
    return CompositionSpec(
        items = project.clips.map { itemSpecOf(it, project.originalAudioMuted) },
        outputSize = outputSize,
        texts = project.textOverlays.filter { it.text.isNotBlank() }.map { textSpecOf(it, outputSize) },
        audioLanes = audioLanesOf(project),
    )
}

private fun audioLanesOf(project: Project): List<List<AudioItemSpec>> {
    val videoDuration = project.totalDurationMs()
    return project.audioLanes().map { lane ->
        var cursor = 0L
        lane.mapNotNull { audio ->
            val placement = audio.placementWithin(videoDuration) ?: return@mapNotNull null
            val (fadeIn, fadeOut) = clampFades(audio.fadeInMs, audio.fadeOutMs, placement.timelineDurationMs)
            AudioItemSpec(
                uri = audio.uri,
                sourceDurationMs = audio.sourceDurationMs,
                gapBeforeMs = placement.timelineStartMs - cursor,
                clipStartMs = placement.sourceStartMs,
                clipEndMs = placement.sourceEndMs,
                speed = audio.speed,
                sound = SoundSpec(audio.volume, fadeIn, fadeOut, placement.timelineDurationMs, audio.voiceEffect.pitch),
            ).also { cursor = placement.timelineStartMs + placement.timelineDurationMs }
        }
    }.filter { it.isNotEmpty() }
}

private fun itemSpecOf(clip: Clip, originalAudioMuted: Boolean): ItemSpec {
    val visual = VisualSpec(filterEffectsFor(clip.filter), clip.rotationDegrees)
    return when (clip.type) {
        ClipType.VIDEO -> ItemSpec.Video(
            uri = clip.uri,
            sourceDurationMs = clip.sourceDurationMs,
            clipStartMs = clip.trimStartMs,
            clipEndMs = clip.trimEndMs,
            speed = clip.speed,
            sound = clip.timelineDurationMs().let { length ->
                val (fadeIn, fadeOut) = clampFades(clip.fadeInMs, clip.fadeOutMs, length)
                SoundSpec(if (clip.muted || originalAudioMuted) 0f else clip.volume, fadeIn, fadeOut, length)
            },
            visual = visual,
        )
        ClipType.IMAGE -> ItemSpec.Image(uri = clip.uri, durationMs = clip.trimEndMs - clip.trimStartMs, visual = visual)
    }
}

private fun textSpecOf(overlay: TextOverlay, outputSize: OutputSize): TextSpec {
    val (x, y) = toNdc(overlay.xNorm, overlay.yNorm)
    return TextSpec(
        id = overlay.id,
        text = overlay.text,
        startUs = overlay.startMs * 1_000,
        endUs = overlay.endMs * 1_000,
        anchorX = x,
        anchorY = y,
        textSizePx = textSizePx(overlay.textSizeSp, minOf(outputSize.width, outputSize.height)),
        colorArgb = overlay.colorArgb,
        backgroundArgb = overlay.backgroundArgb,
    )
}

/** Whether a text overlay is on screen at composition time [presentationTimeUs]. */
fun TextSpec.isVisibleAt(presentationTimeUs: Long): Boolean = presentationTimeUs in startUs until endUs

/** A colour effect, described without Media3 types. */
sealed interface FilterEffect {
    /** -1..1 added to each channel. */
    data class Brightness(val amount: Float) : FilterEffect

    /** -1..1. */
    data class Contrast(val amount: Float) : FilterEffect

    /** -100..100. */
    data class Saturation(val amount: Float) : FilterEffect

    data object Grayscale : FilterEffect

    data class RgbScale(val red: Float, val green: Float, val blue: Float) : FilterEffect

    /** 4x4 column-major RGB matrix (OpenGL layout), as Media3's RgbMatrix expects. */
    data class Matrix(val values: List<Float>) : FilterEffect
}

fun filterEffectsFor(filter: FilterType): List<FilterEffect> = when (filter) {
    FilterType.NONE -> emptyList()
    FilterType.BRIGHTNESS -> listOf(FilterEffect.Brightness(0.12f))
    FilterType.CONTRAST -> listOf(FilterEffect.Contrast(0.3f))
    FilterType.SATURATION -> listOf(FilterEffect.Saturation(45f))
    FilterType.GRAYSCALE -> listOf(FilterEffect.Grayscale)
    FilterType.WARM -> listOf(FilterEffect.RgbScale(1.1f, 1.0f, 0.85f))
    FilterType.COOL -> listOf(FilterEffect.RgbScale(0.88f, 1.0f, 1.12f))
    FilterType.VINTAGE -> listOf(FilterEffect.Matrix(VINTAGE_MATRIX), FilterEffect.Contrast(-0.08f))
}

/**
 * Classic sepia (rows: R' = .393R + .769G + .189B, G' = .349R + .686G + .168B,
 * B' = .272R + .534G + .131B) blended 80/20 with the original, written column-major.
 */
val VINTAGE_MATRIX: List<Float> = run {
    val sepia = arrayOf(
        floatArrayOf(0.393f, 0.769f, 0.189f),
        floatArrayOf(0.349f, 0.686f, 0.168f),
        floatArrayOf(0.272f, 0.534f, 0.131f),
    )
    val blend = 0.8f
    val values = MutableList(16) { 0f }
    for (column in 0..2) {
        for (row in 0..2) {
            val identity = if (row == column) 1f else 0f
            values[column * 4 + row] = blend * sepia[row][column] + (1 - blend) * identity
        }
    }
    values[15] = 1f
    values
}

package com.savie.precut.media

import androidx.annotation.OptIn
import androidx.media3.common.C
import androidx.media3.common.MediaItem
import androidx.media3.common.SpeedParameters
import androidx.media3.common.util.ExperimentalApi
import androidx.media3.transformer.Composition
import androidx.media3.transformer.EditedMediaItem
import androidx.media3.transformer.EditedMediaItemSequence
import androidx.media3.transformer.Effects
import com.savie.precut.model.OutputSize
import com.savie.precut.model.Project
import javax.inject.Inject

/** The single Project → Composition path shared by preview and export. */
class CompositionBuilder @Inject constructor(private val effectsFactory: EffectsFactory) {

    /** Returns null when the project has nothing to play. */
    fun build(project: Project): Composition? {
        val spec = compositionSpecOf(project)
        if (spec.items.isEmpty()) return null
        val sequence = EditedMediaItemSequence.Builder(setOf(C.TRACK_TYPE_AUDIO, C.TRACK_TYPE_VIDEO))
            .addItems(spec.items.map { toEditedMediaItem(it, spec.outputSize) })
            .build()
        val builder = Composition.Builder(listOf(sequence) + spec.audioLanes.map(::audioSequence))
        effectsFactory.textOverlayEffect(spec.texts, spec.outputSize)?.let { overlay ->
            builder.setEffects(Effects(/* audioProcessors= */ emptyList(), /* videoEffects= */ listOf(overlay)))
        }
        return builder.build()
    }

    /** One audio row: for each clip, a silent gap up to its start, then the clip. */
    private fun audioSequence(lane: List<AudioItemSpec>): EditedMediaItemSequence {
        val builder = EditedMediaItemSequence.Builder(setOf(C.TRACK_TYPE_AUDIO))
        lane.forEach { audio ->
            if (audio.gapBeforeMs > 0) builder.addGap(audio.gapBeforeMs * 1_000)
            val mediaItem = MediaItem.Builder()
                .setUri(audio.uri)
                .setClippingConfiguration(
                    MediaItem.ClippingConfiguration.Builder()
                        .setStartPositionMs(audio.clipStartMs)
                        .setEndPositionMs(audio.clipEndMs)
                        .build(),
                )
                .build()
            builder.addItem(
                EditedMediaItem.Builder(mediaItem)
                    .setDurationUs(audio.sourceDurationMs * 1_000)
                    .setEffects(Effects(effectsFactory.audioProcessors(audio.sound), emptyList()))
                    .apply { if (audio.speed != 1f) applySpeed(audio.speed, capFrameRate = false) }
                    .build(),
            )
        }
        return builder.build()
    }

    private fun toEditedMediaItem(item: ItemSpec, outputSize: OutputSize): EditedMediaItem {
        val audio = if (item is ItemSpec.Video) effectsFactory.audioProcessors(item.sound) else emptyList()
        val effects = Effects(audio, effectsFactory.videoEffects(item.visual, outputSize))
        return when (item) {
            is ItemSpec.Video -> {
                val mediaItem = MediaItem.Builder()
                    .setUri(item.uri)
                    .setClippingConfiguration(
                        MediaItem.ClippingConfiguration.Builder()
                            .setStartPositionMs(item.clipStartMs)
                            .setEndPositionMs(item.clipEndMs)
                            .build(),
                    )
                    .build()
                EditedMediaItem.Builder(mediaItem)
                    // CompositionPlayer requires the pre-clipping, pre-speed source duration.
                    .setDurationUs(item.sourceDurationMs * 1_000)
                    .setEffects(effects)
                    .apply { if (item.speed != 1f) applySpeed(item.speed) }
                    .build()
            }
            is ItemSpec.Image -> {
                val mediaItem = MediaItem.Builder()
                    .setUri(item.uri)
                    .setImageDurationMs(item.durationMs)
                    .build()
                EditedMediaItem.Builder(mediaItem)
                    .setDurationUs(item.durationMs * 1_000)
                    .setFrameRate(IMAGE_FRAME_RATE)
                    .setEffects(effects)
                    .build()
            }
        }
    }

    /**
     * Constant speed for preview and export alike, keeping the audio's pitch. Sped-up clips get a
     * frame-rate cap so 4x footage doesn't produce a 120+ fps output.
     */
    @OptIn(ExperimentalApi::class) // SpeedParameters (pitch control) is experimental in Media3 1.11.
    private fun EditedMediaItem.Builder.applySpeed(speed: Float, capFrameRate: Boolean = true) {
        setSpeed(SpeedParameters(ConstantSpeedProvider(speed), /* shouldMaintainPitch= */ true))
        if (capFrameRate && speed > 1f) setFrameRate(MAX_FRAME_RATE)
    }

    private companion object {
        const val IMAGE_FRAME_RATE = 30
        const val MAX_FRAME_RATE = 60
    }
}

