import android.content.Context
import android.graphics.Bitmap
import com.savie.precut.di.IoDispatcher
import com.savie.precut.model.Project
import dagger.hilt.android.qualifiers.ApplicationContext
import kotlinx.coroutines.CoroutineDispatcher
import kotlinx.coroutines.withContext
import java.io.File
import java.io.IOException
import javax.inject.Inject

/** Draft covers: a JPEG of the first clip's first frame, stored in app files. */
class ProjectCoverMaker @Inject constructor(
    @ApplicationContext private val context: Context,
    private val thumbnails: ThumbnailLoader,
    @IoDispatcher private val ioDispatcher: CoroutineDispatcher,
) {
    /** What the cover depends on; null when there's nothing to show. */
    fun keyFor(project: Project): String? =
        project.clips.firstOrNull()?.let { "${it.uri}|${it.type}|${it.trimStartMs}|${it.sourceRotationDegrees}" }

    /** Writes a new cover file (a fresh name per key, so image caches never show a stale one). */
    suspend fun make(project: Project, key: String): String? {
        val clip = project.clips.firstOrNull() ?: return null
        val bitmap = thumbnails.load(ThumbnailKey(clip.uri, clip.type, clip.trimStartMs, COVER_HEIGHT_PX, clip.sourceRotationDegrees))
            ?: return null
        return withContext(ioDispatcher) {
            try {
                val dir = File(context.filesDir, COVER_DIR).apply { mkdirs() }
                val file = File(dir, "${project.id}-${key.hashCode().toUInt()}.jpg")
                file.outputStream().use { bitmap.compress(Bitmap.CompressFormat.JPEG, 85, it) }
                file.absolutePath
            } catch (_: IOException) {
                null
            }
        }
    }

    fun delete(path: String?) {
        path?.let { File(it).delete() }
    }

    private companion object {
        const val COVER_DIR = "covers"
        const val COVER_HEIGHT_PX = 360
    }
}
package com.savie.precut.data

import com.savie.precut.data.db.ProjectDao
import com.savie.precut.data.db.ProjectEntity
import com.savie.precut.media.ProjectCoverMaker
import com.savie.precut.model.Project
import com.savie.precut.model.totalDurationMs
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.map
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock
import javax.inject.Inject
import javax.inject.Singleton

/** Projects in Room as JSON, with a cover image regenerated only when the first clip changes. */
@Singleton
class RoomProjectRepository @Inject constructor(
    private val dao: ProjectDao,
    private val covers: ProjectCoverMaker,
) : ProjectRepository {

    // Serializes read-modify-write of a row (cover bookkeeping) across concurrent saves.
    private val lock = Mutex()

    override suspend fun save(project: Project) = lock.withLock {
        val existing = dao.get(project.id)
        val key = covers.keyFor(project)
        val coverPath = when {
            key == null -> null.also { covers.delete(existing?.coverPath) }
            key == existing?.coverKey && existing.coverPath != null -> existing.coverPath
            else -> covers.make(project, key)?.also { if (it != existing?.coverPath) covers.delete(existing?.coverPath) }
        }
        dao.upsert(
            ProjectEntity(
                id = project.id,
                name = project.name,
                json = ProjectSerializer.encode(project),
                coverPath = coverPath,
