package com.savie.precut.model

import kotlin.math.exp
import kotlin.math.ln
import kotlin.math.roundToInt

/** Clip speed range (CapCut's normal speed). */
const val MIN_CLIP_SPEED = 0.1f
const val MAX_CLIP_SPEED = 100f

/**
 * Logarithmic speed slider: position 0..1 maps to [MIN_CLIP_SPEED]..[MAX_CLIP_SPEED] so 1x sits
 * a third of the way along and every doubling is the same distance.
 */
object SpeedScale {
    private val logMin = ln(MIN_CLIP_SPEED.toDouble())
    private val logRange = ln(MAX_CLIP_SPEED.toDouble()) - logMin

    fun toSlider(speed: Float): Float =
        ((ln(speed.coerceIn(MIN_CLIP_SPEED, MAX_CLIP_SPEED).toDouble()) - logMin) / logRange).toFloat()

    /** The speed at slider [position], rounded to a readable step (0.1x below 10x, 1x above). */
    fun fromSlider(position: Float): Float {
        val raw = exp(logMin + position.coerceIn(0f, 1f) * logRange).toFloat()
        val rounded = if (raw < 10f) (raw * 10).roundToInt() / 10f else raw.roundToInt().toFloat()
        return rounded.coerceIn(MIN_CLIP_SPEED, MAX_CLIP_SPEED)
    }
}
