48	@Composable
49	fun EditorScreen(
50	    onBack: () -> Unit,
51	    onExport: (projectId: String) -> Unit,
52	    viewModel: EditorViewModel = hiltViewModel(),
53	) {
54	    val uiState by viewModel.uiState.collectAsStateWithLifecycle()
55	    val previewState by viewModel.previewState.collectAsStateWithLifecycle()
56	    val canSplit by viewModel.canSplit.collectAsStateWithLifecycle()
57	    val snackbarHostState = remember { SnackbarHostState() }
58	    val scope = rememberCoroutineScope()
59	    val resources = LocalResources.current
60	
61	    LifecycleEventEffect(Lifecycle.Event.ON_STOP) { viewModel.onScreenStopped() }
62	
63	    val picker = rememberLauncherForActivityResult(PickMultipleVisualMedia()) { uris ->
64	        viewModel.onMediaPicked(uris.map(Uri::toString))
65	    }
66	    // OpenDocument (not GetContent) so the music Uri can be kept across restarts.
67	    val musicPicker = rememberLauncherForActivityResult(OpenDocument()) { uri ->
68	        viewModel.audio.onMusicPicked(uri?.toString())
69	    }
70	    val replacementPicker = rememberLauncherForActivityResult(PickVisualMedia()) { uri ->
71	        viewModel.onReplacementPicked(uri?.toString())
72	    }
73	    val coverPicker = rememberLauncherForActivityResult(PickVisualMedia()) { uri ->
74	        viewModel.cover.onImagePicked(uri?.toString())
75	    }
76	    val camera = rememberCameraLaunchers(viewModel::onCaptureResult)
77	    val micPermission = rememberLauncherForActivityResult(RequestPermission()) { granted ->
78	        if (granted) viewModel.audio.onRecordStart(hasPermission = true)
79	    }
80	    ObserveAsEvents(viewModel.events) { event ->
81	        val message = when (event) {
82	            is EditorEvent.SomeFilesSkipped ->
83	                resources.getQuantityString(R.plurals.home_import_skipped, event.count, event.count)
84	            EditorEvent.NothingImported -> resources.getString(R.string.home_import_nothing)
85	            EditorEvent.SpeedNotForPhotos -> resources.getString(R.string.speed_not_for_photos)
86	            EditorEvent.MusicImportFailed -> resources.getString(R.string.audio_import_failed)
87	            EditorEvent.RecordingFailed -> resources.getString(R.string.voiceover_failed)
88	            EditorEvent.NothingToExtract -> resources.getString(R.string.audio_nothing_to_extract)
89	            EditorEvent.PickReplacement -> {
90	                replacementPicker.launch(PickVisualMediaRequest(PickVisualMedia.ImageAndVideo))
91	                return@ObserveAsEvents
92	            }
93	            EditorEvent.PickCoverImage -> {
94	                coverPicker.launch(PickVisualMediaRequest(PickVisualMedia.ImageOnly))
95	                return@ObserveAsEvents
96	            }
97	            is EditorEvent.LaunchCamera -> {
98	                camera.launch(event.cameraUri, event.video)
99	                return@ObserveAsEvents
100	            }
101	            EditorEvent.RequestMicPermission -> {
102	                micPermission.launch(Manifest.permission.RECORD_AUDIO)
103	                return@ObserveAsEvents
104	            }
105	            EditorEvent.PickMusic -> {
106	                musicPicker.launch(arrayOf("audio/*"))
107	                return@ObserveAsEvents
108	            }
109	        }
110	        scope.launch { snackbarHostState.showSnackbar(message) }
111	    }
112	    val timelineActions = rememberTimelineActions(viewModel)
113	
114	    Box(Modifier.fillMaxSize()) {
115	    Scaffold(
116	        topBar = {
117	            val ready = uiState as? EditorUiState.Ready
118	            EditorTopBar(
119	                canExport = ready != null && ready.project.clips.isNotEmpty() && ready.missingIds.isEmpty(),
120	                canUndo = ready?.canUndo == true,
121	                canRedo = ready?.canRedo == true,
122	                onBack = onBack,
123	                onUndo = viewModel::onUndo,
124	                onRedo = viewModel::onRedo,
125	                onExport = { onExport(viewModel.projectId) },
126	            )
127	        },
128	        snackbarHost = { SnackbarHost(snackbarHostState) },
129	    ) { innerPadding ->
130	        val modifier = Modifier
131	            .fillMaxSize()
132	            .padding(innerPadding)
133	        when (val state = uiState) {
134	            EditorUiState.Loading -> Box(modifier, contentAlignment = Alignment.Center) {
135	                CircularProgressIndicator()
136	            }
137	            EditorUiState.NotFound -> Box(modifier, contentAlignment = Alignment.Center) {
138	                Text(stringResource(R.string.editor_not_found))
139	            }
140	            // imePadding: the text tool's keyboard pushes the panel up and shrinks the preview.
