        Slider(value = value, onValueChange = onValueChange, onValueChangeFinished = onFinished, valueRange = range, modifier = Modifier.weight(1f))
    }
}

private fun Modifier.fillMaxWidthCompat(): Modifier = this.then(androidx.compose.foundation.layout.fillMaxWidth().let { Modifier.fillMaxWidthModifier() })
