  hslColor.y = clamp(hslColor.y + uSaturationAdjustment, 0.0, 1.0);
  hslColor.z = clamp(hslColor.z + uLightnessAdjustment, 0.0, 1.0);

  gl_FragColor = vec4(hslToRgb(hslColor), inputColor.a);
}

