package com.savie.precut.ui.editor.tools


/** A horizontally scrolling row of [ToolButton]s on the toolbar surface. */
@Composable
fun ToolRow(modifier: Modifier = Modifier, content: @Composable RowScope.() -> Unit) {
    Surface(color = MaterialTheme.colorScheme.surfaceContainer, modifier = modifier.fillMaxWidth()) {
        Row(
            modifier = Modifier
                .horizontalScroll(rememberScrollState())
                .padding(horizontal = 4.dp, vertical = 8.dp),
            content = content,
        )
    }
}

/** Icon-over-label tool button, 64dp wide. */
@Composable
fun ToolButton(
    @DrawableRes icon: Int,
    @StringRes label: Int,
    enabled: Boolean = true,
    onClick: () -> Unit,
) {
    Column(
        horizontalAlignment = Alignment.CenterHorizontally,
        verticalArrangement = Arrangement.spacedBy(4.dp),
        modifier = Modifier
            .width(64.dp)
            .alpha(if (enabled) 1f else 0.38f)
            .clickable(enabled = enabled, role = Role.Button, onClick = onClick)
            .padding(vertical = 6.dp),
    ) {
        Icon(painterResource(icon), contentDescription = null)
        Text(stringResource(label), style = MaterialTheme.typography.labelMedium)
    }
}
=== tools/ToolPanel.kt
package com.savie.precut.ui.editor.tools


/** Shell shared by every tool panel: a title row with Done, then the tool's controls. */
@Composable
fun ToolPanel(
    title: String,
    onDone: () -> Unit,
    modifier: Modifier = Modifier,
    /** Extra header buttons, before Done (e.g. "Apply to all"). */
    actions: @Composable RowScope.() -> Unit = {},
    content: @Composable ColumnScope.() -> Unit,
) {
    Surface(color = MaterialTheme.colorScheme.surfaceContainer, modifier = modifier.fillMaxWidth()) {
        Column(Modifier.padding(horizontal = 16.dp, vertical = 8.dp)) {
            Row(verticalAlignment = Alignment.CenterVertically) {
                Text(title, style = MaterialTheme.typography.titleSmall, modifier = Modifier.weight(1f))
                actions()
                TextButton(onClick = onDone) { Text(stringResource(R.string.action_done)) }
            }
            content()
        }
    }
}
=== EditorTopBar.kt
package com.savie.precut.ui.editor


@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun EditorTopBar(
    canExport: Boolean,
    canUndo: Boolean,
    canRedo: Boolean,
    onBack: () -> Unit,
    onUndo: () -> Unit,
    onRedo: () -> Unit,
    onExport: () -> Unit,
) {
    TopAppBar(
        title = {},
        navigationIcon = {
            IconButton(onClick = onBack) {
                Icon(Icons.AutoMirrored.Filled.ArrowBack, contentDescription = stringResource(R.string.action_back))
            }
        },
        actions = {
            IconButton(onClick = onUndo, enabled = canUndo) {
                Icon(painterResource(R.drawable.ic_undo), contentDescription = stringResource(R.string.action_undo))
            }
            IconButton(onClick = onRedo, enabled = canRedo) {
                Icon(painterResource(R.drawable.ic_redo), contentDescription = stringResource(R.string.action_redo))
            }
            Button(
                onClick = onExport,
                enabled = canExport,
                contentPadding = PaddingValues(horizontal = 18.dp),
                modifier = Modifier.padding(horizontal = 8.dp),
            ) {
                Text(stringResource(R.string.action_export))
            }
        },
    )
}
