=== timeline/MuteOriginalButton.kt
package com.savie.precut.ui.editor.timeline


internal val MuteButtonSize = 36.dp

/** CapCut's "Mute clip audio" switch, pinned at the left of the clip strip. */
@Composable
fun MuteOriginalButton(muted: Boolean, onClick: () -> Unit, modifier: Modifier = Modifier) {
    Box(
        modifier
            .size(MuteButtonSize)
            .clip(CircleShape)
            .background(Ink2.copy(alpha = 0.9f))
            .clickable(role = Role.Switch, onClick = onClick),
        contentAlignment = Alignment.Center,
    ) {
        Icon(
            painterResource(if (muted) R.drawable.ic_volume_off else R.drawable.ic_volume),
            contentDescription = stringResource(if (muted) R.string.audio_unmute_clips else R.string.audio_mute_clips),
            tint = if (muted) Accent else TextPrimary,
            modifier = Modifier.size(20.dp),
        )
    }
}
=== MissingMediaBanner.kt
package com.savie.precut.ui.editor


/** Shown when some media can't be opened: select a red clip to Replace it, or remove them all. */
@Composable
fun MissingMediaBanner(count: Int, onRemoveAll: () -> Unit, modifier: Modifier = Modifier) {
    Surface(color = MaterialTheme.colorScheme.errorContainer, modifier = modifier.fillMaxWidth()) {
        Row(Modifier.padding(start = 16.dp, end = 8.dp), verticalAlignment = Alignment.CenterVertically) {
            Text(
                pluralStringResource(R.plurals.missing_media, count, count),
                style = MaterialTheme.typography.bodySmall,
                color = MaterialTheme.colorScheme.onErrorContainer,
                modifier = Modifier.weight(1f).padding(vertical = 8.dp),
            )
            TextButton(onClick = onRemoveAll) { Text(stringResource(R.string.missing_remove_all)) }
        }
    }
}

