/** [v] rotated clockwise (screen space) by [degrees]. */
private fun rotate(v: Offset, degrees: Float): Offset {
    val r = Math.toRadians(degrees.toDouble())
    return Offset((v.x * cos(r) - v.y * sin(r)).toFloat(), (v.x * sin(r) + v.y * cos(r)).toFloat())
}

/** A 24 dp white handle with an Ink0 icon, centred on [at]. */
@Composable
private fun TextHandle(icon: Int, description: String, at: Offset, input: () -> Modifier) {
    Box(
        Modifier
            .offset { IntOffset((at.x - 12.dp.toPx()).roundToInt(), (at.y - 12.dp.toPx()).roundToInt()) }
            .size(24.dp)
            .clip(CircleShape)
            .background(Color.White)
            .then(input())
            .semantics { contentDescription = description },
        contentAlignment = Alignment.Center,
    ) {
        Icon(painterResource(icon), contentDescription = null, tint = Ink0, modifier = Modifier.size(16.dp))
    }
}

/** The text box's 1.5 dp dashed white outline. */
private fun Modifier.dashedOutline(shape: RoundedCornerShape): Modifier = drawBehind {
    val outline = shape.createOutline(size, layoutDirection, this)
    drawOutline(outline, Color.White, style = Stroke(1.5.dp.toPx(), pathEffect = PathEffect.dashPathEffect(floatArrayOf(6.dp.toPx(), 4.dp.toPx()))))
}''')
