@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun ExportScreen(
    onClose: () -> Unit,
    viewModel: ExportViewModel = hiltViewModel(),
) {
    val uiState by viewModel.uiState.collectAsStateWithLifecycle()
    val context = LocalContext.current
    val shareTitle = stringResource(R.string.export_share_title)

    // Android 8–9 need storage permission to write to the shared Movies folder.
    val permissionLauncher = rememberLauncherForActivityResult(ActivityResultContracts.RequestPermission()) { granted ->
        if (granted) viewModel.start() else viewModel.onPermissionDenied()
    }
    val startExport = {
        if (needsStoragePermission(context)) {
            permissionLauncher.launch(Manifest.permission.WRITE_EXTERNAL_STORAGE)
        } else {
            viewModel.start()
        }
    }

    LaunchedEffect(Unit) {
        if (viewModel.uiState.value == ExportUiState.Idle) startExport()
    }

    Scaffold(
        topBar = { TopAppBar(title = { Text(stringResource(R.string.export_title)) }) },
    ) { innerPadding ->
        ExportContent(
            state = uiState,
            contentPadding = innerPadding,
            onCancel = {
                viewModel.cancel()
                onClose()
            },
            onRetry = startExport,
            onOpen = { uri ->
                val intent = Intent(Intent.ACTION_VIEW)
                    .setDataAndType(uri.toUri(), VIDEO_MIME)
                    .addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)
                context.startActivity(intent)
            },
            onShare = { uri ->
                val intent = Intent(Intent.ACTION_SEND)
                    .setType(VIDEO_MIME)
                    .putExtra(Intent.EXTRA_STREAM, uri.toUri())
                    .addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)
                context.startActivity(Intent.createChooser(intent, shareTitle))
            },
            onDone = onClose,
        )
    }
}

private const val VIDEO_MIME = "video/mp4"

private fun needsStoragePermission(context: Context): Boolean =
    Build.VERSION.SDK_INT < Build.VERSION_CODES.Q &&
        ContextCompat.checkSelfPermission(context, Manifest.permission.WRITE_EXTERNAL_STORAGE) !=
        PackageManager.PERMISSION_GRANTED
            _uiState.value = ExportUiState.Exporting(percent = null)
            exporter.export(project).collect { exportState ->
                when (exportState) {
                    is ExportState.Running -> _uiState.value = ExportUiState.Exporting(exportState.percent)
                    is ExportState.Failed -> _uiState.value =
                        ExportUiState.Failed(ExportFailure.EXPORT_FAILED, exportState.cause.message)
                    is ExportState.Success -> {
                        _uiState.value = ExportUiState.Saving
                        _uiState.value = saver.saveVideo(exportState.file, displayName()).fold(
                            onSuccess = { ExportUiState.Done(it) },
                            onFailure = { ExportUiState.Failed(ExportFailure.SAVE_FAILED, it.message) },
                        )
                    }
                }
            }
        }
    }

    fun onPermissionDenied() {
        _uiState.value = ExportUiState.Failed(ExportFailure.PERMISSION_DENIED)
    }

    fun cancel() {
        job?.cancel()
        job = null
    }

    private fun displayName(): String =
        "PreCut_" + FILE_TIME.format(clock.instant().atZone(ZoneId.systemDefault())) + ".mp4"

    private companion object {
        val FILE_TIME: DateTimeFormatter = DateTimeFormatter.ofPattern("yyyyMMdd_HHmmss", Locale.ROOT)
    }
}
