            val path = project.coverPath
            if (path != null) {
                // FillWidth keeps the cover's own 9:16 or 1:1 shape, so the grid is masonry.
                AsyncImage(model = java.io.File(path), contentDescription = null, contentScale = ContentScale.FillWidth, modifier = Modifier.fillMaxWidth())
            } else {
