import androidx.hilt.lifecycle.viewmodel.compose.hiltViewModel
import androidx.lifecycle.Lifecycle
import androidx.lifecycle.compose.LifecycleEventEffect
import androidx.lifecycle.compose.collectAsStateWithLifecycle
import com.savie.precut.R
import com.savie.precut.ui.components.ObserveAsEvents
import com.savie.precut.ui.editor.preview.FullScreenPreview
import com.savie.precut.ui.components.rememberCameraLaunchers
import kotlinx.coroutines.launch

@Composable
fun EditorScreen(
    onBack: () -> Unit,
    onExport: (projectId: String) -> Unit,
    viewModel: EditorViewModel = hiltViewModel(),
) {
    val uiState by viewModel.uiState.collectAsStateWithLifecycle()
    // Kept as a State and read only where needed: the playhead changes every frame while
    // playing or scrubbing, and the whole editor must not recompose with it.
    val previewState = viewModel.previewState.collectAsStateWithLifecycle()
    val canSplit by viewModel.canSplit.collectAsStateWithLifecycle()
    val snackbarHostState = remember { SnackbarHostState() }
    val scope = rememberCoroutineScope()
    val resources = LocalResources.current

    LifecycleEventEffect(Lifecycle.Event.ON_STOP) { viewModel.onScreenStopped() }

    val picker = rememberLauncherForActivityResult(PickMultipleVisualMedia()) { uris ->
        viewModel.onMediaPicked(uris.map(Uri::toString))
    }
    // OpenDocument (not GetContent) so the music Uri can be kept across restarts.
    val musicPicker = rememberLauncherForActivityResult(OpenDocument()) { uri ->
        viewModel.audio.onMusicPicked(uri?.toString())
    }
    val replacementPicker = rememberLauncherForActivityResult(PickVisualMedia()) { uri ->
        viewModel.onReplacementPicked(uri?.toString())
    }
    val coverPicker = rememberLauncherForActivityResult(PickVisualMedia()) { uri ->
        viewModel.cover.onImagePicked(uri?.toString())
    }
    val camera = rememberCameraLaunchers(viewModel::onCaptureResult)
    // `.cube` files have no standard MIME type, so any file can be picked and is validated.
    val lutPicker = rememberLauncherForActivityResult(OpenDocument()) { uri ->
        viewModel.look.onImportLut(uri?.toString())
    }
    val micPermission = rememberLauncherForActivityResult(RequestPermission()) { granted ->
        if (granted) viewModel.audio.onRecordStart(hasPermission = true)
    }
    ObserveAsEvents(viewModel.events) { event ->
        val message = when (event) {
            is EditorEvent.SomeFilesSkipped ->
                resources.getQuantityString(R.plurals.home_import_skipped, event.count, event.count)
            EditorEvent.NothingImported -> resources.getString(R.string.home_import_nothing)
            EditorEvent.SpeedNotForPhotos -> resources.getString(R.string.speed_not_for_photos)
            EditorEvent.MusicImportFailed -> resources.getString(R.string.audio_import_failed)
            EditorEvent.RecordingFailed -> resources.getString(R.string.voiceover_failed)
            EditorEvent.NothingToExtract -> resources.getString(R.string.audio_nothing_to_extract)
            EditorEvent.PickReplacement -> {
                replacementPicker.launch(PickVisualMediaRequest(PickVisualMedia.ImageAndVideo))
                return@ObserveAsEvents
            }
            EditorEvent.LutImportFailed -> resources.getString(R.string.filter_lut_import_failed)
            EditorEvent.PickLut -> {
                lutPicker.launch(arrayOf("*/*"))
                return@ObserveAsEvents
            }
            EditorEvent.PickCoverImage -> {
                coverPicker.launch(PickVisualMediaRequest(PickVisualMedia.ImageOnly))
                return@ObserveAsEvents
            }
            is EditorEvent.LaunchCamera -> {
                camera.launch(event.cameraUri, event.video)
                return@ObserveAsEvents
            }
            EditorEvent.RequestMicPermission -> {
                micPermission.launch(Manifest.permission.RECORD_AUDIO)
                return@ObserveAsEvents
            }
            EditorEvent.PickMusic -> {
                musicPicker.launch(arrayOf("audio/*"))
                return@ObserveAsEvents
            }
        }
        scope.launch { snackbarHostState.showSnackbar(message) }
    }
    val timelineActions = rememberTimelineActions(viewModel)
    var renaming by rememberSaveable { mutableStateOf(false) }
    val topBarActions = remember(viewModel) {
        object : EditorTopBarActions {
            override fun onBack() = onBack()
            override fun onStartRename() {
                renaming = true
            }
            override fun onRename(name: String) {
                viewModel.onRename(name)
                renaming = false
            }
            override fun onCancelRename() {
                renaming = false
            }
            override fun onUndo() {
                viewModel.onUndo()
            }
            override fun onRedo() {
                viewModel.onRedo()
            }
            override fun onExport() = onExport(viewModel.projectId)
        }
    }
    BackHandler(enabled = renaming) { renaming = false }

    Box(Modifier.fillMaxSize()) {
        Scaffold(
            topBar = {
                val ready = uiState as? EditorUiState.Ready
                EditorTopBar(
                    title = ready?.project?.let { projectDisplayName(it.name, it.createdAt) }.orEmpty(),
                    canExport = ready != null && ready.project.clips.isNotEmpty() && ready.missingIds.isEmpty(),
                    canUndo = ready?.canUndo == true,
                    canRedo = ready?.canRedo == true,
                    renaming = renaming && ready != null,
                    actions = topBarActions,
                )
            },
            snackbarHost = {
                // Above the toolbar, which reaches down behind the navigation bar.
                SnackbarHost(snackbarHostState, Modifier.navigationBarsPadding().padding(bottom = 72.dp))
            },
            // The top bar pads for the status bar and the bottom panel for the navigation bar.
            contentWindowInsets = WindowInsets(0, 0, 0, 0),
        ) { innerPadding ->
            val modifier = Modifier
                .fillMaxSize()
                .padding(innerPadding)
            when (val state = uiState) {
                EditorUiState.Loading -> Box(modifier, contentAlignment = Alignment.Center) {
                    CircularProgressIndicator()
                }
                EditorUiState.NotFound -> Box(modifier, contentAlignment = Alignment.Center) {
                    Text(stringResource(R.string.editor_not_found))
                }
                is EditorUiState.Ready -> EditorContent(
                    state = state,
                    dimmed = renaming,
                    previewState = previewState,
                    canSplit = canSplit,
                    viewModel = viewModel,
                    timelineActions = timelineActions,
                    onAddMedia = { picker.launch(PickVisualMediaRequest(PickVisualMedia.ImageAndVideo)) },
                    modifier = modifier,
                )
            }
        }
        // Drawn over the whole screen, top bar included.
        (uiState as? EditorUiState.Ready)?.takeIf { it.fullScreen && it.project.clips.isNotEmpty() }?.let {
            FullScreenPreview(
                player = viewModel.player,
                previewState = previewState,
                onPlayPause = viewModel::onPlayPause,
                onScrubStart = viewModel::onScrubStart,
                onScrubEnd = viewModel::onScrubEnd,
                onSeek = viewModel::onSeek,
                onClose = { viewModel.onFullScreen(false) },
            )
        }
    }
}

package com.savie.precut.media

import androidx.annotation.OptIn
import androidx.media3.common.C
import androidx.media3.common.MediaItem
import androidx.media3.common.SpeedParameters
import androidx.media3.common.util.ExperimentalApi
import androidx.media3.transformer.Composition
import androidx.media3.transformer.EditedMediaItem
import androidx.media3.transformer.EditedMediaItemSequence
import androidx.media3.transformer.Effects
import com.savie.precut.model.DEFAULT_SHORT_SIDE_PX
import com.savie.precut.model.OutputSize
import com.savie.precut.model.Project
import javax.inject.Inject

/** The single Project → Composition path shared by preview and export. */
class CompositionBuilder @Inject constructor(private val effectsFactory: EffectsFactory) {

    /** Returns null when the project has nothing to play. [shortSidePx] sets the output size. */
    fun build(project: Project, shortSidePx: Int = DEFAULT_SHORT_SIDE_PX): Composition? {
        val spec = compositionSpecOf(project, shortSidePx)
        if (spec.items.isEmpty()) return null
        val sequence = EditedMediaItemSequence.Builder(setOf(C.TRACK_TYPE_AUDIO, C.TRACK_TYPE_VIDEO))
            .addItems(spec.items.map { toEditedMediaItem(it, spec.outputSize) })
            .build()
        val builder = Composition.Builder(listOf(sequence) + spec.audioLanes.map(::audioSequence))
            // The look shader works in SDR; HDR sources are tone-mapped (HDR export: Phase 12).
            .setHdrMode(Composition.HDR_MODE_TONE_MAP_HDR_TO_SDR_USING_OPEN_GL)
        // Layers grade the composed frame; text and the cover go on top, ungraded.
        val videoEffects = effectsFactory.lookLayerEffects(spec.lookLayers) +
            listOfNotNull(effectsFactory.overlayEffect(spec.texts, spec.cover, spec.outputSize))
        if (videoEffects.isNotEmpty()) builder.setEffects(Effects(/* audioProcessors= */ emptyList(), videoEffects))
        return builder.build()
    }

    /** One audio row: for each clip, a silent gap up to its start, then the clip. */
    private fun audioSequence(lane: List<AudioItemSpec>): EditedMediaItemSequence {
        val builder = EditedMediaItemSequence.Builder(setOf(C.TRACK_TYPE_AUDIO))
        lane.forEach { audio ->
            if (audio.gapBeforeMs > 0) builder.addGap(audio.gapBeforeMs * 1_000)
            val mediaItem = MediaItem.Builder()
                .setUri(audio.uri)
                .setClippingConfiguration(
                    MediaItem.ClippingConfiguration.Builder()
                        .setStartPositionMs(audio.clipStartMs)
                        .setEndPositionMs(audio.clipEndMs)
                        .build(),
                )
                .build()
            builder.addItem(
                EditedMediaItem.Builder(mediaItem)
                    .setDurationUs(audio.sourceDurationMs * 1_000)
                    .setEffects(Effects(effectsFactory.audioProcessors(audio.sound), emptyList()))
                    .apply { if (audio.speed != 1f) applySpeed(audio.speed, capFrameRate = false) }
                    .build(),
            )
        }
        return builder.build()
    }

    private fun toEditedMediaItem(item: ItemSpec, outputSize: OutputSize): EditedMediaItem {
        val audio = if (item is ItemSpec.Video) effectsFactory.audioProcessors(item.sound) else emptyList()
        val effects = Effects(audio, effectsFactory.videoEffects(item.visual, outputSize))
        return when (item) {
            is ItemSpec.Video -> {
                val mediaItem = MediaItem.Builder()
                    .setUri(item.uri)
                    .setClippingConfiguration(
                        MediaItem.ClippingConfiguration.Builder()
                            .setStartPositionMs(item.clipStartMs)
                            .setEndPositionMs(item.clipEndMs)
                            .build(),
                    )
                    .build()
                EditedMediaItem.Builder(mediaItem)
                    // CompositionPlayer requires the pre-clipping, pre-speed source duration.
                    .setDurationUs(item.sourceDurationMs * 1_000)
                    .setEffects(effects)
                    .apply { if (item.speed != 1f) applySpeed(item.speed, keepPitch = item.keepPitch) }
                    .build()
            }
            is ItemSpec.Image -> {
                val mediaItem = MediaItem.Builder()
                    .setUri(item.uri)
                    .setImageDurationMs(item.durationMs)
                    .build()
                EditedMediaItem.Builder(mediaItem)
                    .setDurationUs(item.durationMs * 1_000)
                    .setFrameRate(IMAGE_FRAME_RATE)
                    .setEffects(effects)
                    .build()
            }
        }
    }

    /**
     * Constant speed for preview and export alike, optionally keeping the audio's pitch. Sped-up clips get a
     * frame-rate cap so 4x footage doesn't produce a 120+ fps output.
     */
    @OptIn(ExperimentalApi::class) // SpeedParameters (pitch control) is experimental in Media3 1.11.
    private fun EditedMediaItem.Builder.applySpeed(speed: Float, capFrameRate: Boolean = true, keepPitch: Boolean = true) {
        setSpeed(SpeedParameters(ConstantSpeedProvider(speed), /* shouldMaintainPitch= */ keepPitch))
        if (capFrameRate && speed > 1f) setFrameRate(MAX_FRAME_RATE)
    }

    private companion object {
        const val IMAGE_FRAME_RATE = 30
        const val MAX_FRAME_RATE = 60
    }
}

package com.savie.precut.media

import com.savie.precut.model.Clip
import com.savie.precut.model.ClipType
import com.savie.precut.model.OutputSize
import com.savie.precut.model.Project
import com.savie.precut.model.TextOverlay
import com.savie.precut.model.CoverSource
import com.savie.precut.model.DEFAULT_SHORT_SIDE_PX
import com.savie.precut.model.coverSource
import com.savie.precut.model.look.ClipLook
import com.savie.precut.model.outputSize
import com.savie.precut.model.audioLanes
import com.savie.precut.model.edit.clampFades
import com.savie.precut.model.placementWithin
import com.savie.precut.model.timelineDurationMs
import com.savie.precut.model.totalDurationMs

/**
 * Pure description of the Media3 composition for a project. Kept free of Media3/Android types so
 * the Project → composition mapping can be unit-tested on the JVM.
 */
data class CompositionSpec(
    val items: List<ItemSpec>,
    val outputSize: OutputSize,
    /** Applied once to the whole composition, in timeline time. */
    val texts: List<TextSpec> = emptyList(),
    /** Audio rows, each mixed in as its own audio-only sequence. */
    val audioLanes: List<List<AudioItemSpec>> = emptyList(),
    /** Shown full-frame over the first frame of the video (CapCut "add cover to video"). */
    val cover: CoverSpec? = null,
    /** Filter/adjust layers over the whole frame, in timeline time, in stacking order. */
    val lookLayers: List<LookLayerSpec> = emptyList(),
)

/** A look layer: grades the composed frame between [startUs] and [endUs]. */
data class LookLayerSpec(val startUs: Long, val endUs: Long, val look: ClipLook)

/** The cover picture, shown until [endUs]. */
data class CoverSpec(val source: CoverSource, val endUs: Long)

/** How long the cover shows: one frame at 30 fps. */
const val COVER_DURATION_US = 1_000_000L / 30

/** One audio clip after placement: silence for [gapBeforeMs], then its (already cut) range. */
data class AudioItemSpec(
    val uri: String,
    val sourceDurationMs: Long,
    val gapBeforeMs: Long,
    val clipStartMs: Long,
    val clipEndMs: Long,
    val speed: Float,
    val sound: SoundSpec,
)

/** How an item's audio is shaped, in its timeline length [lengthMs]. */
data class SoundSpec(
    val volume: Float = 1f,
    val fadeInMs: Long = 0L,
    val fadeOutMs: Long = 0L,
    val lengthMs: Long = 0L,
    val pitch: Float = 1f,
)

/** Look shared by every item: grading, then user rotation, then fit into the frame. */
data class VisualSpec(
    /** Null when the clip isn't graded. */
    val look: ClipLook? = null,
    /** Clockwise, 0/90/180/270. */
    val rotationDegrees: Int = 0,
)

sealed interface ItemSpec {
    val visual: VisualSpec

    data class Video(
        val uri: String,
        val sourceDurationMs: Long,
        val clipStartMs: Long,
        val clipEndMs: Long,
        val speed: Float = 1f,
        val keepPitch: Boolean = true,
        /** The clip's own sound; volume 0 when muted or when all original audio is muted. */
        val sound: SoundSpec = SoundSpec(),
        override val visual: VisualSpec = VisualSpec(),
    ) : ItemSpec

    data class Image(
        val uri: String,
        val durationMs: Long,
        override val visual: VisualSpec = VisualSpec(),
    ) : ItemSpec
}

/** A text overlay ready to render: pixel size in the output frame and a Media3 NDC anchor. */
data class TextSpec(
    val id: String,
    val text: String,
    val startUs: Long,
    val endUs: Long,
    /** -1 (left) .. 1 (right). */
    val anchorX: Float,
    /** -1 (bottom) .. 1 (top). */
    val anchorY: Float,
    val textSizePx: Float,
    val colorArgb: Int,
    val backgroundArgb: Int?,
    /** Clockwise. */
    val rotationDegrees: Float = 0f,
    val opacity: Float = 1f,
)

/**
 * Text sizes are "sp on a [TEXT_REFERENCE_WIDTH_DP]-wide screen", scaled to the output's short
 * side, so the editor's on-screen ghost and the export agree regardless of resolution.
 */
const val TEXT_REFERENCE_WIDTH_DP = 360f

fun textSizePx(textSizeSp: Float, frameShortSidePx: Int): Float = textSizeSp * frameShortSidePx / TEXT_REFERENCE_WIDTH_DP

/** Maps a 0..1 position (y down) to Media3's normalized device coordinates (y up). */
fun toNdc(xNorm: Float, yNorm: Float): Pair<Float, Float> = (xNorm * 2f - 1f) to (1f - yNorm * 2f)

/** The composition for [project] with an output short side of [shortSidePx] (preview renders smaller). */
fun compositionSpecOf(project: Project, shortSidePx: Int = DEFAULT_SHORT_SIDE_PX): CompositionSpec {
    val outputSize = project.outputSize(shortSidePx)
    return CompositionSpec(
        items = project.clips.map { itemSpecOf(it, project.originalAudioMuted) },
        outputSize = outputSize,
        texts = project.textOverlays.filter { it.text.isNotBlank() }.map { textSpecOf(it, outputSize) },
        audioLanes = audioLanesOf(project),
        cover = project.coverSource()?.takeIf { project.coverInExport && project.cover != null }
            ?.let { CoverSpec(it, COVER_DURATION_US) },
        lookLayers = project.lookLayers.filterNot { it.look.isIdentity }
            .map { LookLayerSpec(it.startMs * 1_000, it.endMs * 1_000, it.look) },
    )
}

private fun audioLanesOf(project: Project): List<List<AudioItemSpec>> {
    val videoDuration = project.totalDurationMs()
    return project.audioLanes().map { lane ->
        var cursor = 0L
        lane.mapNotNull { audio ->
            val placement = audio.placementWithin(videoDuration) ?: return@mapNotNull null
            val (fadeIn, fadeOut) = clampFades(audio.fadeInMs, audio.fadeOutMs, placement.timelineDurationMs)
            AudioItemSpec(
                uri = audio.uri,
                sourceDurationMs = audio.sourceDurationMs,
                gapBeforeMs = placement.timelineStartMs - cursor,
                clipStartMs = placement.sourceStartMs,
                clipEndMs = placement.sourceEndMs,
                speed = audio.speed,
                sound = SoundSpec(audio.volume, fadeIn, fadeOut, placement.timelineDurationMs, audio.voiceEffect.pitch),
            ).also { cursor = placement.timelineStartMs + placement.timelineDurationMs }
        }
    }.filter { it.isNotEmpty() }
}

private fun itemSpecOf(clip: Clip, originalAudioMuted: Boolean): ItemSpec {
    val visual = VisualSpec(clip.look.takeUnless { it.isIdentity }, clip.rotationDegrees)
    return when (clip.type) {
        ClipType.VIDEO -> ItemSpec.Video(
            uri = clip.uri,
            sourceDurationMs = clip.sourceDurationMs,
            clipStartMs = clip.trimStartMs,
            clipEndMs = clip.trimEndMs,
            speed = clip.speed,
            keepPitch = clip.keepPitch,
            sound = clip.timelineDurationMs().let { length ->
                val (fadeIn, fadeOut) = clampFades(clip.fadeInMs, clip.fadeOutMs, length)
                SoundSpec(if (clip.muted || originalAudioMuted) 0f else clip.volume, fadeIn, fadeOut, length)
            },
            visual = visual,
        )
        ClipType.IMAGE -> ItemSpec.Image(uri = clip.uri, durationMs = clip.trimEndMs - clip.trimStartMs, visual = visual)
    }
}

private fun textSpecOf(overlay: TextOverlay, outputSize: OutputSize): TextSpec {
    val (x, y) = toNdc(overlay.xNorm, overlay.yNorm)
    return TextSpec(
        id = overlay.id,
        text = overlay.text,
        startUs = overlay.startMs * 1_000,
        endUs = overlay.endMs * 1_000,
        anchorX = x,
        anchorY = y,
        textSizePx = textSizePx(overlay.textSizeSp, minOf(outputSize.width, outputSize.height)),
        colorArgb = overlay.colorArgb,
        backgroundArgb = overlay.backgroundArgb,
        rotationDegrees = overlay.rotationDegrees,
        opacity = overlay.opacity.coerceIn(0f, 1f),
    )
}

/** Whether a text overlay is on screen at composition time [presentationTimeUs]. */
fun TextSpec.isVisibleAt(presentationTimeUs: Long): Boolean = presentationTimeUs in startUs until endUs

